SysDataModelXML.JavaScript:
scan_ajax=function(id, arr, res) {
	var parajson = {
		loginID: arr[1],
		par: {
			dmCode: arr[2],
			dmNum: arr[3], 
//根据标签编号获取标签内容的模型
			
Para: arr[4] 
//传入的参数值，标签号码
		}
	};
	mui.ajax(arr[0], {
		data: parajson,
		dataType: 'json',
 //服务器返回json格式数据
		
type: 'post', //HTTP请求类型
		async: false,
		timeout: 30000, 
//超时时间设置为10秒；
		success: function(re) {
			try {
				var result = (re.data.Table[0].TAGCONTENT);
				deal_json(JSON.parse(result)); 
//解析json
				
if(JSON.parse(result)['打印批次']==""){
alert("打印批次不存在");
}
			} catch(e) {
				plus.nativeUI.toast("解析失败");
				document.getElementById(id).value = res;
			} finally {
				plus.nativeUI.closeWaiting();
			}
		},
		error: function(xhr, type, errorThrown) {
			
//异常处理；
			
plus.nativeUI.closeWaiting();
			plus.nativeUI.toast(type);
		}
	});
}
